using VisualRelay.Core.Execution;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

/// <summary>
/// Unit tests for <see cref="NonoDiagnosticsJsonParser.TryExtractDenials"/> —
/// the tolerant JSON-tail parser that finds the last balanced <c>{…}</c>
/// containing <c>"denials"</c>, extracts the denial records, and strips the
/// JSON block from the captured output.  Absent, truncated, or malformed JSON
/// must never throw — the parser returns false with the output unchanged.
/// </summary>
public sealed class NonoDiagnosticsJsonParserTests
{
    // ── Happy path: valid trailing JSON with denials ──────────────────

    [Fact]
    public void TryExtractDenials_WithDenialsPresent_ExtractsAndStrips()
    {
        var json = "{\"denials\":[{\"operation\":\"file-write-create\",\"target\":\"/Volumes/Tera/.TemporaryItems/foo\"}]}";
        var output = "some command output\nmore output\n" + json;

        var result = NonoDiagnosticsJsonParser.TryExtractDenials(output, out var stripped, out var denials);

        Assert.True(result);
        Assert.NotNull(denials);
        Assert.Single(denials);
        Assert.Equal("file-write-create", denials[0].Operation);
        Assert.Equal("/Volumes/Tera/.TemporaryItems/foo", denials[0].Target);
        // JSON block must be removed from the output handed to callers.
        Assert.DoesNotContain("{", stripped);
        Assert.Equal("some command output\nmore output\n", stripped);
    }

    [Fact]
    public void TryExtractDenials_EmptyDenials_StillExtracts()
    {
        var output = "output line\n{\"denials\":[]}";

        var result = NonoDiagnosticsJsonParser.TryExtractDenials(output, out var stripped, out var denials);

        Assert.True(result);
        Assert.NotNull(denials);
        Assert.Empty(denials);
        Assert.Equal("output line\n", stripped);
    }

    [Fact]
    public void TryExtractDenials_MultipleDenials_ExtractsAll()
    {
        var json = "{\"denials\":[" +
            "{\"operation\":\"file-write-create\",\"target\":\"/tmp/a\"}," +
            "{\"operation\":\"file-read\",\"target\":\"/tmp/b\"}" +
            "]}";
        var output = "output\n" + json;

        var result = NonoDiagnosticsJsonParser.TryExtractDenials(output, out var stripped, out var denials);

        Assert.True(result);
        Assert.Equal(2, denials.Count);
        Assert.Equal("file-write-create", denials[0].Operation);
        Assert.Equal("/tmp/a", denials[0].Target);
        Assert.Equal("file-read", denials[1].Operation);
        Assert.Equal("/tmp/b", denials[1].Target);
        Assert.Equal("output\n", stripped);
    }

    // ── Absent / no denials key ───────────────────────────────────────

    [Fact]
    public void TryExtractDenials_NoJson_ReturnsFalse()
    {
        var output = "plain command output\nno json here";

        var result = NonoDiagnosticsJsonParser.TryExtractDenials(output, out var stripped, out var denials);

        Assert.False(result);
        Assert.Empty(denials);
        Assert.Equal(output, stripped);
    }

    [Fact]
    public void TryExtractDenials_JsonWithoutDenialsKey_ReturnsFalseAndDoesNotStrip()
    {
        // A trailing JSON object that does NOT contain "denials" is not
        // diagnostics — it may be legitimate command output.  Must not be stripped.
        var output = "output\n{\"other\":\"value\"}";

        var result = NonoDiagnosticsJsonParser.TryExtractDenials(output, out var stripped, out var denials);

        Assert.False(result);
        Assert.Empty(denials);
        Assert.Equal(output, stripped);
    }

    // ── Malformed / truncated ─────────────────────────────────────────

    [Fact]
    public void TryExtractDenials_MalformedJson_ReturnsFalse()
    {
        // Truncated — missing closing brace and bracket.
        var output = "output\n{\"denials\":[{\"operation\":\"file-write-create\"";

        var result = NonoDiagnosticsJsonParser.TryExtractDenials(output, out var stripped, out var denials);

        Assert.False(result);
        Assert.Empty(denials);
        Assert.Equal(output, stripped);
    }

    [Fact]
    public void TryExtractDenials_UnbalancedBraces_ReturnsFalse()
    {
        var output = "output\n{\"denials\":[{\"operation\":\"file-write-create\",\"target\":\"/tmp/foo\"}]";

        var result = NonoDiagnosticsJsonParser.TryExtractDenials(output, out var stripped, out var denials);

        Assert.False(result);
        Assert.Empty(denials);
        Assert.Equal(output, stripped);
    }

    // ── Edge cases ────────────────────────────────────────────────────

    [Fact]
    public void TryExtractDenials_JsonFollowedByTrailingContent_StripsJsonOnly()
    {
        // Diagnostics JSON is NOT the last thing in the output — there is
        // trailing content after it.  Only the JSON block itself is stripped.
        var output = "output\n{\"denials\":[{\"operation\":\"file-write-create\",\"target\":\"/tmp/foo\"}]}\ntrailing content\nmore trailing";

        var result = NonoDiagnosticsJsonParser.TryExtractDenials(output, out var stripped, out var denials);

        Assert.True(result);
        Assert.Single(denials);
        Assert.Equal("/tmp/foo", denials[0].Target);
        Assert.Equal("output\n\ntrailing content\nmore trailing", stripped);
    }

    [Fact]
    public void TryExtractDenials_MultipleJsonBlocks_PicksLastOneWithDenials()
    {
        // An earlier {…} block without "denials" is ignored; only the LAST
        // balanced block containing "denials" is extracted.
        var output = "{\"other\":1}\nreal output\n{\"denials\":[{\"operation\":\"file-write-create\",\"target\":\"/tmp/bar\"}]}";

        var result = NonoDiagnosticsJsonParser.TryExtractDenials(output, out var stripped, out var denials);

        Assert.True(result);
        Assert.Single(denials);
        Assert.Equal("/tmp/bar", denials[0].Target);
        Assert.DoesNotContain("denials", stripped);
    }

    [Fact]
    public void TryExtractDenials_EmptyOutput_ReturnsFalse()
    {
        var result = NonoDiagnosticsJsonParser.TryExtractDenials("", out var stripped, out var denials);

        Assert.False(result);
        Assert.Empty(denials);
        Assert.Equal("", stripped);
    }

    [Fact]
    public void TryExtractDenials_NullOutput_ReturnsFalse()
    {
        var result = NonoDiagnosticsJsonParser.TryExtractDenials(null!, out var stripped, out var denials);

        Assert.False(result);
        Assert.Empty(denials);
        Assert.Null(stripped);
    }

    [Fact]
    public void TryExtractDenials_JsonAppendedToLastOutputLine_StripsCleanly()
    {
        // JSON may be concatenated to the final line of output (no newline
        // separator).  The parser must still find and strip it.
        var output = "final line{\"denials\":[{\"operation\":\"file-write-create\",\"target\":\"/tmp/foo\"}]}";

        var result = NonoDiagnosticsJsonParser.TryExtractDenials(output, out var stripped, out var denials);

        Assert.True(result);
        Assert.Single(denials);
        Assert.Equal("/tmp/foo", denials[0].Target);
        Assert.Equal("final line", stripped);
    }
}

using VisualRelay.Core.Execution;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

/// <summary>
/// Unit tests for the enriched distilled reason that replaces the bare
/// "setup check failure" string with the failing check name, its command,
/// and the first denial path when present.  Also asserts flag-reason
/// truncation safety (first line must stay within 200 chars).
/// </summary>
public sealed class VerifyReasonConstructionTests
{
    // ── Guard red with denial ─────────────────────────────────────────

    [Fact]
    public void BuildSetupCheckFailureReason_GuardRedWithDenial_NamesGuardAndCommandAndDenialPath()
    {
        var denials = new List<SandboxDenial>
        {
            new("file-write-create", "/Volumes/Tera/.TemporaryItems/NSIRD_swift-build_abc")
        };
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: null,
            BootstrapCommand: null,
            BootstrapOutput: null,
            GuardCheck: "red",
            GuardCommand: "swift build",
            GuardOutput: "error: sandbox",
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "green",
            TestCommand: "swift test",
            TestExitCode: 0,
            GuardDenials: denials);

        var reason = RelayDriver.BuildSetupCheckFailureReason(checks);

        Assert.Contains("setup check failure", reason);
        Assert.Contains("guard", reason);
        Assert.Contains("swift build", reason);
        Assert.Contains("sandbox denial", reason);
        Assert.Contains("/Volumes/Tera/.TemporaryItems/NSIRD_swift-build_abc", reason);
        Assert.DoesNotContain("bootstrap", reason);
        Assert.DoesNotContain("test", reason);
    }

    // ── Bootstrap red (no denial) ─────────────────────────────────────

    [Fact]
    public void BuildSetupCheckFailureReason_BootstrapRedNoDenial_NamesBootstrapAndCommand()
    {
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: "red",
            BootstrapCommand: "nix develop",
            BootstrapOutput: "error: flake not found",
            GuardCheck: null,
            GuardCommand: null,
            GuardOutput: null,
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "red",
            TestCommand: "bun test",
            TestExitCode: 1);

        var reason = RelayDriver.BuildSetupCheckFailureReason(checks);

        Assert.Contains("setup check failure", reason);
        Assert.Contains("bootstrap", reason);
        Assert.Contains("nix develop", reason);
        Assert.DoesNotContain("sandbox denial", reason);
        Assert.DoesNotContain("guard", reason);
    }

    // ── Test green, guard red ─────────────────────────────────────────

    [Fact]
    public void BuildSetupCheckFailureReason_TestGreenGuardRed_NamesGuardNotTest()
    {
        var denials = new List<SandboxDenial>
        {
            new("file-write-create", "/tmp/denied-path")
        };
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: null,
            BootstrapCommand: null,
            BootstrapOutput: null,
            GuardCheck: "red",
            GuardCommand: "./tools/guards/check.sh",
            GuardOutput: "violation found",
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "green",
            TestCommand: "bun test",
            TestExitCode: 0,
            GuardDenials: denials);

        var reason = RelayDriver.BuildSetupCheckFailureReason(checks);

        // The guard is the failing check, not the test.
        Assert.Contains("guard", reason);
        Assert.Contains("check.sh", reason);
        Assert.Contains("sandbox denial", reason);
        Assert.DoesNotContain("bun test", reason);
    }

    // ── Guard red, no denial path ─────────────────────────────────────

    [Fact]
    public void BuildSetupCheckFailureReason_GuardRedNoDenial_OmitsSandboxDenialSuffix()
    {
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: null,
            BootstrapCommand: null,
            BootstrapOutput: null,
            GuardCheck: "red",
            GuardCommand: "./tools/guards/lint.sh",
            GuardOutput: "lint violations found",
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "green",
            TestCommand: "bun test",
            TestExitCode: 0);

        var reason = RelayDriver.BuildSetupCheckFailureReason(checks);

        Assert.Contains("guard", reason);
        Assert.Contains("lint.sh", reason);
        Assert.DoesNotContain("sandbox denial", reason);
    }

    // ── Truncation safety ─────────────────────────────────────────────

    [Fact]
    public void BuildSetupCheckFailureReason_ReasonFirstLine_Within200Chars()
    {
        // The flag-reason path (RelayDriver.VerifyFix.cs:238-239) truncates
        // the first line to 200 chars.  The enriched reason must stay within
        // that bound even with a long denial path.
        var longTarget = new string('x', 300);
        var denials = new List<SandboxDenial>
        {
            new("file-write-create", longTarget)
        };
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: null,
            BootstrapCommand: null,
            BootstrapOutput: null,
            GuardCheck: "red",
            GuardCommand: "swift build",
            GuardOutput: "denied",
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "green",
            TestCommand: "swift test",
            TestExitCode: 0,
            GuardDenials: denials);

        var reason = RelayDriver.BuildSetupCheckFailureReason(checks);
        var firstLine = reason.Split('\n')[0];

        Assert.True(firstLine.Length <= 200,
            $"First line is {firstLine.Length} chars; must be ≤ 200 for flag-reason truncation safety.  " +
            $"Line: '{firstLine}'");
    }

    // ── Bootstrap red AND guard red — picks the first failing check ───

    [Fact]
    public void BuildSetupCheckFailureReason_BootstrapAndGuardRed_PicksFirstFailingCheck()
    {
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: "red",
            BootstrapCommand: "nix develop",
            BootstrapOutput: "error",
            GuardCheck: "red",
            GuardCommand: "swift build",
            GuardOutput: "sandbox denial",
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "green",
            TestCommand: "swift test",
            TestExitCode: 0);

        var reason = RelayDriver.BuildSetupCheckFailureReason(checks);

        // Bootstrap is checked first — it should be the named failure.
        Assert.Contains("bootstrap", reason);
        Assert.Contains("nix develop", reason);
        Assert.DoesNotContain("guard", reason);
    }

    // ── All green — returns empty ─────────────────────────────────────

    [Fact]
    public void BuildSetupCheckFailureReason_AllGreen_ReturnsEmpty()
    {
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: "green",
            BootstrapCommand: "nix develop",
            BootstrapOutput: null,
            GuardCheck: "green",
            GuardCommand: "swift build",
            GuardOutput: null,
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "green",
            TestCommand: "swift test",
            TestExitCode: 0);

        var reason = RelayDriver.BuildSetupCheckFailureReason(checks);

        Assert.Equal(string.Empty, reason);
    }

    // ── Null setupChecks ──────────────────────────────────────────────

    [Fact]
    public void BuildSetupCheckFailureReason_NullSetupChecks_ReturnsBareSetupCheckFailure()
    {
        var reason = RelayDriver.BuildSetupCheckFailureReason(null);

        Assert.Equal("setup check failure", reason);
    }
}

