// ── Request diagnostics (--diagnostics-json) ─────────────────────────

[Fact]
public void BuildNonoPrefix_RequestDiagnosticsTrue_IncludesDiagnosticsJson()
{
    var config = TestConfig();

    var verify = SwivalSubagentRunner.BuildNonoPrefix(config, rollback: false, requestDiagnostics: true);

    Assert.Contains("--diagnostics-json", verify);
    // --diagnostics-json is a nono flag, so it must precede the `--` child separator.
    Assert.True(verify.ToList().IndexOf("--diagnostics-json") < verify.ToList().IndexOf("--"));
}

[Fact]
public void BuildNonoPrefix_RequestDiagnosticsFalse_OmitsDiagnosticsJson()
{
    var config = TestConfig();

    var verify = SwivalSubagentRunner.BuildNonoPrefix(config, rollback: false, requestDiagnostics: false);
    var swival = SwivalSubagentRunner.BuildNonoPrefix(config, rollback: true);

    Assert.DoesNotContain("--diagnostics-json", verify);
    Assert.DoesNotContain("--diagnostics-json", swival);
}

[Fact]
public void BuildNonoPrefix_RequestDiagnostics_IsIndependentOfVerbose()
{
    // requestDiagnostics adds --diagnostics-json regardless of verboseDiagnostics.
    var config = TestConfig();

    var quietWithDiag = SwivalSubagentRunner.BuildNonoPrefix(config, rollback: false, requestDiagnostics: true);
    var verboseWithDiag = SwivalSubagentRunner.BuildNonoPrefix(config, rollback: false, verboseDiagnostics: true, requestDiagnostics: true);

    Assert.Contains("--diagnostics-json", quietWithDiag);
    Assert.Contains("--diagnostics-json", verboseWithDiag);
}

// ── Helpers ─────────────────────────────────────────────────────────

private static string ProfilePath => NonoProfileEnsurer.ResolveProfilePath();

// ── Diagnostics-json toggle ─────────────────────────────────────────

[Fact]
public void VerifyPrefix_ContainsDiagnosticsJson()
{
    Assert.SkipUnless(!OperatingSystem.IsWindows(), "Unix nono wrapper (Windows uses the MXC seam)");
    var config = TestConfig();
    // SandboxedTestRunner always passes requestDiagnostics: true — the
    // verification path is the ONLY path that requests --diagnostics-json.
    var prefix = SwivalSubagentRunner.BuildNonoPrefix(config, rollback: false, requestDiagnostics: true);

    Assert.Contains("--diagnostics-json", prefix);
    Assert.True(prefix.ToList().IndexOf("--diagnostics-json") < prefix.ToList().IndexOf("--"));
}

[Fact]
public void SwivalPrefix_DoesNotContainDiagnosticsJson()
{
    Assert.SkipUnless(!OperatingSystem.IsWindows(), "Unix nono wrapper (Windows uses the MXC seam)");
    var config = TestConfig();
    // Swival-agent path: rollback: true, no requestDiagnostics.
    var prefix = SwivalSubagentRunner.BuildNonoPrefix(config, rollback: true);

    Assert.DoesNotContain("--diagnostics-json", prefix);
}

// ── Helpers ────────────────────────────────────────────────────────

// The VR-owned profile abs path the prefix now carries (--profile <abs>),

    [Fact]
    public void CapForState_NullOrEmpty_ReturnsNull()
    {
        Assert.Null(SetupCheckDiagnostic.CapForState(null));
        Assert.Null(SetupCheckDiagnostic.CapForState(""));
    }

    // ── ToSummaryLines with denials ────────────────────────────────────

    [Fact]
    public void ToSummaryLines_WithDenials_RendersDenialPathAlongsideRedCheck()
    {
        var denials = new List<SandboxDenial>
        {
            new("file-write-create", "/Volumes/Tera/.TemporaryItems/NSIRD_swift-build_abc")
        };
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: null,
            BootstrapCommand: null,
            BootstrapOutput: null,
            GuardCheck: "red",
            GuardCommand: "swift build",
            GuardOutput: "error",
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "green",
            TestCommand: "swift test",
            TestExitCode: 0,
            GuardDenials: denials);

        var summary = checks.ToSummaryLines();

        Assert.Contains("✗ guard: red", summary);
        Assert.Contains("sandbox denial", summary);
        Assert.Contains("/Volumes/Tera/.TemporaryItems/NSIRD_swift-build_abc", summary);
    }

    [Fact]
    public void ToSummaryLines_WithoutDenials_RedCheckHasNoDenialSuffix()
    {
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: null,
            BootstrapCommand: null,
            BootstrapOutput: null,
            GuardCheck: "red",
            GuardCommand: "swift build",
            GuardOutput: "lint violations",
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "green",
            TestCommand: "swift test",
            TestExitCode: 0);

        var summary = checks.ToSummaryLines();

        Assert.Contains("✗ guard: red", summary);
        Assert.DoesNotContain("sandbox denial", summary);
    }

    [Fact]
    public void ToSummaryLines_GuardGreenWithDenials_DoesNotRenderDenial()
    {
        // Denials on a green check are not surfaced in summary lines
        // (the denial didn't cause a failure).
        var denials = new List<SandboxDenial>
        {
            new("file-read", "/tmp/some-path")
        };
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: null,
            BootstrapCommand: null,
            BootstrapOutput: null,
            GuardCheck: "green",
            GuardCommand: "swift build",
            GuardOutput: null,
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "green",
            TestCommand: "swift test",
            TestExitCode: 0,
            GuardDenials: denials);

        var summary = checks.ToSummaryLines();

        Assert.Contains("✓ guard: green", summary);
        Assert.DoesNotContain("sandbox denial", summary);
    }

    // ── JSON serialization includes denials ────────────────────────────

    [Fact]
    public void Serialization_IncludesDenialFields()
    {
        var denials = new List<SandboxDenial>
        {
            new("file-write-create", "/Volumes/Tera/.TemporaryItems/NSIRD_swift-build_abc"),
            new("file-read", "/tmp/other")
        };
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: null,
            BootstrapCommand: null,
            BootstrapOutput: null,
            GuardCheck: "red",
            GuardCommand: "swift build",
            GuardOutput: "sandbox denial",
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "green",
            TestCommand: "swift test",
            TestExitCode: 0,
            GuardDenials: denials);

        var json = System.Text.Json.JsonSerializer.Serialize(checks,
            new System.Text.Json.JsonSerializerOptions
            {
                PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase,
                WriteIndented = true
            });

        Assert.Contains("guardDenials", json);
        Assert.Contains("file-write-create", json);
        Assert.Contains("/Volumes/Tera/.TemporaryItems/NSIRD_swift-build_abc", json);
        Assert.Contains("file-read", json);
        Assert.Contains("/tmp/other", json);
    }

    [Fact]
    public void Serialization_NoDenials_OmitsDenialFields()
    {
        var checks = new RelayDriver.SetupCheckResults(
            BootstrapCheck: "green",
            BootstrapCommand: "nix develop",
            BootstrapOutput: null,
            GuardCheck: "green",
            GuardCommand: null,
            GuardOutput: null,
            NewGuardProbeCheck: null,
            NewGuardProbeOutput: null,
            TestCheck: "green",
            TestCommand: "bun test",
            TestExitCode: 0);

        var json = System.Text.Json.JsonSerializer.Serialize(checks,
            new System.Text.Json.JsonSerializerOptions
            {
                PropertyNamingPolicy = System.Text.Json.JsonNamingPolicy.CamelCase,
                WriteIndented = true
            });

        Assert.DoesNotContain("Denials", json);
        Assert.DoesNotContain("sandbox denial", json);
    }
}

